    // SizesFor returns the Sizes used by a compiler for an architecture.
    // The result is nil if a compiler/architecture pair is not known.
    //
    // Supported architectures for compiler "gc":
    // "386", "amd64", "amd64p32", "arm", "arm64", "loong64", "mips", "mipsle",
    // "mips64", "mips64le", "ppc64", "ppc64le", "riscv64", "s390x", "sparc64", "wasm".
    Sizes SizesFor(gocpp::string compiler, gocpp::string arch)
    {
        //Go switch emulation
        {
            auto condition = compiler;
            int conditionId = -1;
            if(condition == "gc"_s) { conditionId = 0; }
            else if(condition == "gccgo"_s) { conditionId = 1; }
            switch(conditionId)
            {
                case 0:
                    if(auto s = gcSizesFor(compiler, arch); s != nullptr)
                    {
                        return Sizes(s);
                    }
                    break;
                case 1:
                    if(auto [s, ok] = gccgoArchSizes[arch]; ok)
                    {
                        return Sizes(s);
                    }
                    break;
            }
        }
        return nullptr;
    }

